-- CITS internal issue closure. MariaDB 11.4. Back up first and run once before deploying.
SET NAMES utf8mb4;
alter table `issues` modify `stage` varchar(10) null;
alter table `issues` add `close_target` varchar(30) null;
alter table `issues` add `close_from` varchar(30) null;
alter table `issues` add `close_reason` varchar(1000) null;
alter table `issues` add `close_meeting_item_id` bigint unsigned null;
alter table `issues` add constraint `issues_close_meeting_item_id_foreign` foreign key (`close_meeting_item_id`) references `meeting_items` (`id`) on delete set null;
alter table `issues` add `closed_at` datetime null;
alter table `issues` add `closed_by` bigint unsigned null;
alter table `issues` add constraint `issues_closed_by_foreign` foreign key (`closed_by`) references `users` (`id`);
create table `issue_close_tasks` (`id` bigint unsigned not null auto_increment primary key, `issue_id` bigint unsigned not null, `round` int unsigned not null, `role` varchar(20) not null, `user_id` bigint unsigned null, `status` varchar(16) not null, `note` varchar(1000) null, `done_by` bigint unsigned null, `done_at` datetime null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_uca1400_ai_ci' engine = InnoDB;
alter table `issue_close_tasks` add constraint `issue_close_tasks_issue_id_foreign` foreign key (`issue_id`) references `issues` (`id`);
alter table `issue_close_tasks` add constraint `issue_close_tasks_user_id_foreign` foreign key (`user_id`) references `users` (`id`);
alter table `issue_close_tasks` add constraint `issue_close_tasks_done_by_foreign` foreign key (`done_by`) references `users` (`id`);
alter table `issue_close_tasks` add unique `issue_close_tasks_issue_id_round_role_unique`(`issue_id`, `round`, `role`);
alter table `issue_close_tasks` add index `issue_close_tasks_issue_id_round_status_index`(`issue_id`, `round`, `status`);
alter table `issue_close_tasks` add index `issue_close_tasks_user_id_status_index`(`user_id`, `status`);
